// Adapted (ported Java -> JS) from j5 src/expensetracker/App.java:34-69 @ fe67601
// (run/loadExpenses/saveExpenses reduced to a session driver over injected storage and
// log; exit codes follow the course's exercise-3 answer: a refused startup and a failed
// final save both exit non-zero, and a failed save leaves a recovery snapshot instead of
// throwing the session away).
export async function runSession({ storage, commands, log }) {
  let expenses;
  try {
    expenses = await storage.load();
    log(`Loaded ${expenses.length} expense(s).`);
  } catch (error) {
    log(`Could not load saved expenses: ${error.message}`);
    log('Startup stopped. The saved file was not changed; repair a copy before retrying.');
    return { exitCode: 1, saved: false };
  }

  for (const command of commands) {
    expenses = command(expenses);
  }

  try {
    await storage.save(expenses);
    log('Expenses saved to disk.');
    return { exitCode: 0, saved: true };
  } catch (error) {
    log(`Could not save expenses: ${error.message}`);
    // The session's edits exist only in memory. Exiting 0 here would tell scripts the
    // save worked while every change was thrown away, so: write a recovery snapshot and
    // exit non-zero (review finding 1 / exercise 3).
    await storage.writeRecoverySnapshot(expenses);
    log('Unsaved changes written to the recovery file.');
    return { exitCode: 1, saved: false };
  }
}
